  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Ampicillin, a zwitterionic amino-beta-lactam, had absolute oral bioavailability of 55.3±17.8% in humans after 495 mg p.o. vs IV; its amino acid and lactam motifs are structurally relevant to the query, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Diclofenac, an N-aryl acetic acid, has absolute oral bioavailability of 54% in adult humans; the query contains a benzazepinone N-acetic acid motif, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Solifenacin, a fused bicyclic amine/amide drug, showed 88.0% absolute oral bioavailability in healthy young men; the rigid fused bicyclic scaffold supports high F for the query's benzazepinone system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Imipramine, a tricyclic dibenzazepine, had absolute oral bioavailability of 44.1±4.6%; the tricyclic fused-ring character is analogous to the query's benzazepine core, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Maraviroc, an oral amide/amine drug, had absolute oral bioavailability of 33% at 300 mg in healthy volunteers; even moderate values remain above the 20% threshold, supporting high.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Thalidomide, a lactam/imide fused aromatic system, has probably high oral bioavailability of 80–100% in fasting healthy volunteers; this supports high F for the query's lactam-containing benzazepinone.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high: all relevant human oral bioavailability records for structurally related zwitterionic beta-lactams, N-aryl acetic acids, fused bicyclic lactams, and tricyclic amines are ≥23%, mostly 40–88%, supporting F≥20% for the query.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "No exact ACE-inhibitor/benzazepinone-lysine analog is present in the evidence set.",
    "Possible effects of first-pass metabolism, efflux transporters, and pH-dependent solubility are inferred from analogs rather than measured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

